-- Krok 1 na PROD: kontrola wstępna (musi przejść bez błędu). Nic nie zapisuje.
DO $$
DECLARE missing text;
BEGIN
  SELECT string_agg(r.t || '.' || r.c, ', ') INTO missing
  FROM (VALUES ('users', 'id'), ('users', 'name'), ('users', 'email'), ('users', 'emailVerified'), ('users', 'image'), ('users', 'role'), ('users', 'created_at'), ('users', 'updated_at'), ('users', 'deleted_at'), ('users', 'phone'), ('users', 'blocked_at'), ('users', 'blocked_by'), ('users', 'blocked_reason'), ('producer', 'id'), ('producer', 'user_id'), ('producer', 'nip'), ('producer', 'name'), ('producer', 'country_code'), ('producer', 'rating'), ('producer', 'review_count'), ('producer', 'technology'), ('producer', 'verification_status'), ('producer', 'created_at'), ('producer', 'updated_at'), ('producer', 'deleted_at'), ('producer', 'production_scale'), ('producer', 'inquiry_response_time_label'), ('producer', 'showroom_visit_available'), ('producer', 'showroom_visit_note'), ('producer', 'description'), ('producer', 'communication_locale'), ('producer', 'is_platform_brand'), ('producer_delivery_country', 'producer_id'), ('producer_delivery_country', 'country_code'), ('producer_delivery_country', 'created_at'), ('producer_member', 'id'), ('producer_member', 'producer_id'), ('producer_member', 'user_id'), ('producer_member', 'added_by'), ('producer_member', 'created_at'), ('product_option_group', 'id'), ('product_option_group', 'producer_id'), ('product_option_group', 'name'), ('product_option_group', 'selection_type'), ('product_option_group', 'sort_order'), ('product_option_group', 'created_at'), ('product_option_group', 'updated_at'), ('product_option_group', 'deleted_at'), ('product_option', 'id'), ('product_option', 'group_id'), ('product_option', 'label'), ('product_option', 'price_cents'), ('product_option', 'price_on_request'), ('product_option', 'is_default'), ('product_option', 'sort_order'), ('product_option', 'created_at'), ('product_option', 'updated_at'), ('product_option', 'deleted_at'), ('product_option', 'image_url'), ('product_option', 'price_note'), ('product_option_group_translation', 'id'), ('product_option_group_translation', 'group_id'), ('product_option_group_translation', 'locale'), ('product_option_group_translation', 'name'), ('product_option_group_translation', 'created_at'), ('product_option_group_translation', 'updated_at'), ('product_option_translation', 'id'), ('product_option_translation', 'option_id'), ('product_option_translation', 'locale'), ('product_option_translation', 'label'), ('product_option_translation', 'created_at'), ('product_option_translation', 'updated_at'), ('product_option_translation', 'price_note'), ('product', 'id'), ('product', 'producer_id'), ('product', 'status'), ('product', 'name'), ('product', 'country_of_production'), ('product', 'floor_area_m2'), ('product', 'built_up_area_m2'), ('product', 'description'), ('product', 'completion_standard'), ('product', 'production_lead_time_weeks_min'), ('product', 'production_lead_time_weeks_max'), ('product', 'on_site_assembly_days_min'), ('product', 'on_site_assembly_days_max'), ('product', 'house_price_min_cents'), ('product', 'house_price_max_cents'), ('product', 'structural_warranty_years'), ('product', 'category'), ('product', 'rooms'), ('product', 'bedrooms'), ('product', 'bathrooms'), ('product', 'storeys'), ('product', 'external_dimensions'), ('product', 'roof_type'), ('product', 'construction_system'), ('product', 'foundation_options'), ('product', 'customization_scope'), ('product', 'currency'), ('product', 'price_includes'), ('product', 'price_excludes'), ('product', 'featured'), ('product', 'created_at'), ('product', 'updated_at'), ('product', 'deleted_at'), ('product', 'family'), ('product', 'spa_subcategory'), ('product', 'technical_specs'), ('product', 'cover_image_url'), ('product', 'container_subcategory'), ('product', 'installation_warranty_years'), ('product', 'service_scope_description'), ('product', 'transport_dimensions'), ('product', 'crane_requirements'), ('product', 'min_plot_width_m'), ('product', 'room_layout'), ('product', 'faq'), ('product', 'simplified_permit_eligible'), ('product', 'client_requirements'), ('product', 'video_url'), ('product', 'slug'), ('product', 'outdoor_tv_mounting'), ('product', 'outdoor_tv_sun_exposure'), ('product', 'foundation_status'), ('product_translation', 'id'), ('product_translation', 'product_id'), ('product_translation', 'locale'), ('product_translation', 'name'), ('product_translation', 'description'), ('product_translation', 'created_at'), ('product_translation', 'updated_at'), ('product_translation', 'room_layout'), ('product_translation', 'faq'), ('product_translation', 'ai_generated_name'), ('product_translation', 'ai_generated_description'), ('product_translation', 'ai_translated_from_name'), ('product_translation', 'ai_translated_from_description'), ('product_translation', 'client_requirements'), ('product_translation', 'foundation_options'), ('product_translation', 'technical_specs'), ('product_translation', 'construction_system'), ('product_translation', 'roof_type'), ('product_translation', 'customization_scope'), ('product_translation', 'service_scope_description'), ('product_variant', 'id'), ('product_variant', 'product_id'), ('product_variant', 'completion_standard'), ('product_variant', 'variant_label'), ('product_variant', 'price_min_cents'), ('product_variant', 'price_max_cents'), ('product_variant', 'scope_summary'), ('product_variant', 'is_default'), ('product_variant', 'sort_order'), ('product_variant', 'created_at'), ('product_variant', 'updated_at'), ('product_variant', 'deleted_at'), ('product_variant', 'price_on_request'), ('product_variant', 'excluded_scope'), ('product_option_group_assignment', 'id'), ('product_option_group_assignment', 'product_id'), ('product_option_group_assignment', 'group_id'), ('product_option_group_assignment', 'created_at'), ('document', 'id'), ('document', 'r2_key'), ('document', 'filename'), ('document', 'mime_type'), ('document', 'size_bytes'), ('document', 'purpose'), ('document', 'is_cover'), ('document', 'sort_order'), ('document', 'owner_user_id'), ('document', 'product_id'), ('document', 'order_stage_event_id'), ('document', 'producer_id'), ('document', 'created_at'), ('document', 'deleted_at'), ('document', 'product_variant_id'), ('document', 'project_quote_id'), ('document', 'product_option_id'), ('document', 'floor_level')) AS r(t, c)
  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns k
    WHERE k.table_schema = 'public' AND k.table_name = r.t AND k.column_name = r.c
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Na tej bazie brakuje kolumn (najpierw wdróż migrację 0073): %', missing;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = 'product_family' AND e.enumlabel = 'outdoor-kitchen') THEN
    RAISE EXCEPTION 'Typ product_family nie ma wartości outdoor-kitchen (najpierw wdróż migrację 0073)';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM producer WHERE id = '24e54122-9cf0-470b-96af-6e97e5cfcdf5' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Na tej bazie nie ma producenta Wooden Dream House (24e54122-9cf0-470b-96af-6e97e5cfcdf5)';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(ARRAY['d1412fb0-b85e-442e-9fc1-a9de11b8e265']::text[]) AS o(id) WHERE o.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users u WHERE u.id = o.id)) THEN
    RAISE EXCEPTION 'Brakuje konta właściciela zdjęć Wooden Dream House na tej bazie';
  END IF;
  IF EXISTS (SELECT 1 FROM producer WHERE nip = 'MHE-OWN' AND id <> '5d4b2662-168d-5a6d-a450-935505789db1') THEN
    RAISE EXCEPTION 'NIP MHE-OWN jest już zajęty przez inny wiersz, przerywam';
  END IF;
  IF EXISTS (SELECT 1 FROM product WHERE slug IN ('compact-360-z-lodowka', 'premium-300', 'premium-360', 'sky-kitchen-wood', 'sky-kitchen-slide', 'sky-kitchen-prestige', 'sky-kitchen-prestige-set', 'compact-240', 'compact-320-marrone', 'premium-420') AND id NOT IN (SELECT id FROM product WHERE family = 'outdoor-kitchen')) THEN
    RAISE EXCEPTION 'Adres (slug) jednej z kuchni jest już zajęty przez inny produkt, przerywam';
  END IF;
END $$;
